SELECT id, pond_id, record_date, biomass_kg, fish_count, avg_weight_kg, created_at
FROM biomass_record
WHERE pond_id = #{pondId}
  AND record_date >= #{startDate}
  AND record_date <= #{endDate}
ORDER BY record_date ASC

SELECT id, pond_id, record_date, biomass_kg, fish_count, avg_weight_kg, created_at
FROM biomass_record
WHERE pond_id = #{pondId}
  AND record_date = #{recordDate}
LIMIT 1
